<script setup>
import { computed,ref,watch,nextTick,onMounted,onBeforeUnmount } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { library,words } from '../api/index.js'
import { createReadingPress,readingTokens } from '../utils/readingPress.js'
const route=useRoute(),router=useRouter(),data=ref(null),error=ref(''),loading=ref(false)
const fontSize=ref(21),held=ref(''),selected=ref(''),definition=ref(null),lookupError=ref(''),lookupBusy=ref(false)
const notice=ref(''),saved=ref(''),paragraph=ref(0),audioError=ref('')
let serial=0,lookupSerial=0,lookupController,saveTimer,disposed=false
const bookId=computed(()=>String(route.params.id||''))
const chapterIndex=computed(()=>data.value?.chapters.findIndex(c=>c.id===data.value.chapter.id)??0)
const paragraphs=computed(()=>data.value?.chapter.paragraphs.map(readingTokens)||[])
const press=createReadingPress({onOpen:lookupToken,onCancel:()=>{held.value=''}})
function startPress(word,event,key){if(event.button!==0)return;press.start(word,event);held.value=key}
async function load(){const run=++serial;loading.value=true;error.value='';audioError.value='';press.cancel();selected.value='';notice.value='';saved.value='';
  try{const value=await library.read(bookId.value,route.query.chapter);if(disposed||run!==serial)return;data.value=value;paragraph.value=value.progress.chapterId===value.chapter.id?value.progress.paragraph||0:0;await nextTick();document.getElementById('reader-paragraph-'+paragraph.value)?.scrollIntoView({block:'start'})}
  catch(e){if(run===serial)error.value=e.message}finally{if(run===serial)loading.value=false}}
async function lookupToken(word){if(word.length>64)return;const run=++lookupSerial;lookupController?.abort();lookupController=new AbortController();selected.value=word;definition.value=null;lookupError.value='';lookupBusy.value=true;
  try{const value=await words.lookup(word,lookupController.signal);if(!disposed&&run===lookupSerial)definition.value=value}catch(e){if(run===lookupSerial&&!lookupController.signal.aborted)lookupError.value=e.message}finally{if(run===lookupSerial)lookupBusy.value=false}}
async function aiLookup(){const run=++lookupSerial;lookupBusy.value=true;lookupError.value='';try{const value=await words.lookupAi(selected.value);if(!disposed&&run===lookupSerial)definition.value=value}catch(e){if(run===lookupSerial)lookupError.value=e.message}finally{if(run===lookupSerial)lookupBusy.value=false}}
function closeLookup(){press.cancel();selected.value='';lookupController?.abort();lookupSerial++}
async function addWord(entry){try{await words.favorite(entry.id);saved.value=`已将 ${entry.spelling} 收藏到生词本`}catch(e){lookupError.value=e.message}}
async function flush(){clearTimeout(saveTimer);if(!data.value)return;const id=data.value.book.id,chapterId=data.value.chapter.id,position=paragraph.value;try{await library.saveReading(id,{chapterId,paragraph:position});saved.value='阅读位置已保存'}catch{saved.value='阅读位置暂未同步，稍后重试'}}
function scroll(){press.cancel();if(!data.value||loading.value)return;const elements=document.querySelectorAll('[data-reading-paragraph]');let closest=0,min=Infinity;for(const node of elements){const distance=Math.abs(node.getBoundingClientRect().top-130);if(distance<min){min=distance;closest=Number(node.dataset.readingParagraph)}}paragraph.value=closest;clearTimeout(saveTimer);saveTimer=setTimeout(flush,1000)}
async function go(id){await flush();await router.push({path:route.path,query:{chapter:id}})}
async function showNotice(){try{notice.value=await library.notice(bookId.value)}catch(e){error.value=e.message}}
watch(()=>[route.params.id,route.query.chapter],load,{immediate:true})
onMounted(()=>window.addEventListener('scroll',scroll,{passive:true}))
onBeforeUnmount(()=>{disposed=true;serial++;lookupSerial++;press.cancel();lookupController?.abort();window.removeEventListener('scroll',scroll);void flush()})
</script>
<template>
  <main class="reader-page">
    <router-link class="text-button" to="/library?tab=reading">返回听读空间</router-link>
    <p v-if="error" role="alert">{{ error }} <button class="text-button" @click="load">重试</button></p>
    <p v-if="loading"><LoadingState>正在读取原文与阅读位置…</LoadingState></p>
    <template v-if="data&&!loading">
      <header class="reader-header"><p>{{ data.book.titleZh }} · {{ data.book.author }}</p><h1>{{ data.book.title }}</h1><p class="reader-source">{{ data.book.sourceName }} 编校版 · <a :href="data.book.sourceUrl" target="_blank" rel="noopener noreferrer">来源</a></p></header>
      <div class="reader-tools"><label>章节 <select :value="data.chapter.id" @change="go($event.target.value)"><option v-for="item in data.chapters" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label>字号 <input v-model="fontSize" type="range" min="17" max="29" aria-label="阅读字号"></label><button class="text-button" @click="flush">保存位置</button></div>
      <p class="reader-instruction">长按单词满 5 秒查看释义；移动或松手会取消。键盘可聚焦单词后按 Enter。</p><p class="reader-saved" role="status">{{ saved }}</p>
      <section v-if="data.chapter.audioUrl" class="reader-chapter-audio"><strong>本章真人朗读 · {{ data.book.audio.source }}</strong><audio :key="data.chapter.id" controls preload="none" :src="data.chapter.audioUrl" @error="audioError='外部音频连接暂不可用，可打开官方来源或继续阅读。'" /><p>{{ data.book.audio.note }} <a :href="data.book.audio.sourceUrl" target="_blank" rel="noopener noreferrer">官方音频来源</a></p><p v-if="audioError" role="status">{{ audioError }}</p></section>
      <article class="reader-text" :style="{fontSize:fontSize+'px'}" lang="en"><h2>{{ data.chapter.title }}</h2><p v-for="(tokens,index) in paragraphs" :key="index" :id="'reader-paragraph-'+index" :data-reading-paragraph="index"><template v-for="(token,j) in tokens" :key="j"><span v-if="token.word" role="button" tabindex="0" :aria-label="'长按5秒查释义 '+token.text" :class="['reader-word',{holding:held===`${index}:${j}`}]" @pointerdown="startPress(token.text,$event,`${index}:${j}`)" @pointermove="press.move($event)" @pointerup="press.cancel" @pointercancel="press.cancel" @pointerleave="press.cancel" @contextmenu.prevent @keydown.enter.prevent="!$event.repeat&&lookupToken(token.text)" @keydown.escape="press.cancel">{{ token.text }}</span><template v-else>{{ token.text }}</template></template></p></article>
      <nav class="reader-pagination" aria-label="章节翻页"><button class="btn btn-ghost" :disabled="chapterIndex===0" @click="go(data.chapters[chapterIndex-1].id)">上一章</button><span>{{ chapterIndex+1 }} / {{ data.chapters.length }}</span><button class="btn btn-primary" :disabled="chapterIndex===data.chapters.length-1" @click="go(data.chapters[chapterIndex+1].id)">下一章</button></nav>
      <footer class="reader-license"><p>{{ data.book.licenseLabel }}</p><a :href="data.book.licenseUrl" target="_blank" rel="noopener noreferrer">来源授权声明</a> · <button class="text-button" @click="showNotice">查看保留的原始声明</button><pre v-if="notice">{{ notice }}</pre></footer>
    </template>
    <aside v-if="selected" class="reader-definition" role="dialog" aria-label="单词释义" aria-modal="false"><header><strong lang="en">{{ selected }}</strong><button class="text-button" @click="closeLookup" aria-label="关闭释义">关闭</button></header><p v-if="lookupBusy" role="status">正在查询…</p><p v-if="lookupError" role="alert">{{ lookupError }}</p><template v-if="definition"><article v-for="entry in definition.entries" :key="entry.spelling"><p><strong>{{ entry.spelling }}</strong> {{ entry.phonetic }} {{ entry.pos }}</p><ul><li v-for="meaning in entry.definitions" :key="meaning">{{ meaning }}</li></ul><button v-if="entry.id" class="text-button" @click="addWord(entry)">收藏到生词本</button></article><p v-if="!definition.entries?.length">现有词库暂未找到这个词，可主动选择 AI 补充释义。</p><small>显示词典候选释义，需结合当前句子选择义项。</small></template><div class="lookup-actions"><button class="btn btn-secondary" :disabled="lookupBusy" @click="aiLookup">AI 补充释义</button><router-link class="text-button" :to="{path:'/lookup',query:{q:selected}}">进入查词</router-link></div><small>AI 补释由你点击后调用已配置的文字 API。</small></aside>
  </main>
</template>
<style scoped>
.reader-page{max-width:820px;margin:auto;padding-top:15px}.reader-header{margin:35px 0}.reader-header h1{font:500 clamp(26px,4vw,38px)/1.4 var(--serif)}.reader-header>p{color:var(--ink-soft)}.reader-source,.reader-instruction,.reader-saved,.reader-license{font-size:12px;line-height:1.8;color:var(--ink-soft)}.reader-tools{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap;border-block:1px solid var(--line);padding:15px 0}.reader-tools label{display:flex;align-items:center;gap:8px;font-size:13px}.reader-tools select{max-width:300px;padding:8px;color:var(--ink);background:var(--bg-card);border:1px solid var(--line)}.reader-tools input{width:100px}.reader-text{font-family:Georgia,'Times New Roman',serif;line-height:1.95;margin:32px 0;overflow-wrap:anywhere}.reader-text h2{font-size:1.35em;line-height:1.5;margin:30px 0}.reader-text p{scroll-margin-top:110px;margin-bottom:1.25em}.reader-word{-webkit-touch-callout:none;user-select:none;touch-action:pan-y;cursor:help;border-radius:3px;position:relative}.reader-word:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.reader-word.holding{background:var(--accent-soft)}.reader-word.holding:after{content:'';position:absolute;left:0;bottom:-2px;height:2px;background:var(--accent);animation:reading-hold 5s linear forwards}@keyframes reading-hold{from{width:0}to{width:100%}}.reader-pagination{display:flex;align-items:center;justify-content:space-between;padding:25px 0}.reader-license{border-top:1px solid var(--line);padding:20px 0}.reader-license pre{white-space:pre-wrap;font:inherit}.reader-definition{position:fixed;right:25px;bottom:25px;width:min(420px,calc(100vw - 32px));max-height:75vh;overflow:auto;padding:22px;border:1px solid var(--line);border-radius:14px;background:var(--bg-card);color:var(--ink);z-index:70}.reader-definition header{display:flex;justify-content:space-between;align-items:center;gap:20px}.reader-definition header strong{font-size:24px}.reader-definition p,.reader-definition li{line-height:1.8;font-size:14px}.reader-definition small{font-size:11px;color:var(--ink-soft);line-height:1.8}.lookup-actions{display:flex;align-items:center;gap:20px;margin:20px 0}@media(max-width:600px){.reader-tools{gap:12px}.reader-tools select{max-width:240px}.reader-definition{right:16px;bottom:16px;padding:18px}}
</style>

<style scoped>.reader-chapter-audio{padding:15px;border:1px solid var(--line);border-radius:10px;margin:20px 0}.reader-chapter-audio audio{display:block;width:100%;margin:12px 0}.reader-chapter-audio strong,.reader-chapter-audio p{font-size:12px;line-height:1.8;color:var(--ink-soft)}</style>
